import express, { Express } from 'express';
import { AdvanceOrderUseCase } from '../application/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { GetOrderUseCase } from '../application/GetOrderUseCase';
import { ListOrdersUseCase } from '../application/ListOrdersUseCase';
import { ListProductStockUseCase } from '../application/ListProductStockUseCase';
import { OrderLookupService } from '../application/OrderLookupService';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { StockReservationService } from '../domain/StockReservationService';
import { errorHandler, notFoundHandler } from './http/errorHandler';
import { OrderController } from './http/OrderController';
import { ProductController } from './http/ProductController';
import { seedCatalogue } from './persistence/catalogueSeed';
import { InMemoryOrderRepository } from './persistence/InMemoryOrderRepository';
import { InMemoryProductRepository } from './persistence/InMemoryProductRepository';
import { SystemClock } from './system/SystemClock';
import { UuidGenerator } from './system/UuidGenerator';

/** Composition root: wires repositories, services, use cases and controllers. */
export function createApp(): Express {
  const products = new InMemoryProductRepository();
  const orders = new InMemoryOrderRepository();
  seedCatalogue(products);

  const clock = new SystemClock();
  const stock = new StockReservationService(products);
  const lookup = new OrderLookupService(orders);

  const orderController = new OrderController({
    placeOrder: new PlaceOrderUseCase(orders, stock, new UuidGenerator(), clock),
    advanceOrder: new AdvanceOrderUseCase(orders, lookup, stock, clock),
    cancelOrder: new CancelOrderUseCase(orders, lookup, stock, clock),
    getOrder: new GetOrderUseCase(lookup),
    listOrders: new ListOrdersUseCase(orders),
  });
  const productController = new ProductController(new ListProductStockUseCase(products));

  const app = express();
  app.use(express.json());
  app.use('/orders', orderController.routes());
  app.use('/products', productController.routes());
  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

=====SOURCE-END=====

